<script setup lang="ts">
import {ref,computed} from 'vue'; import {Check,ArrowLeft,ArrowRight,Gift,MapPin,Clock,Wallet} from 'lucide-vue-next'; import {money} from '../data'; import {useShopStore} from '../stores/shop';
const store=useShopStore(),step=ref(0),done=ref(false); const form=ref({first:'',last:'',phone:'',email:'',governorate:'',area:'',block:'',street:'',building:'',floor:'',instructions:'',date:'',slot:'',gift:false,recipient:'',recipientPhone:'',message:'',anonymous:false}); const deliveryFee=ref<number|null>(null); const total=computed(()=>store.cartTotal+(deliveryFee.value||0)); const dates=['Next available · Thu 14 Aug','Fri 15 Aug','Sat 16 Aug']; const slots=['10 AM – 1 PM','1 PM – 4 PM','4 PM – 7 PM']; function next(){if(step.value===0&&form.value.area)deliveryFee.value=1.5;if(step.value<2)step.value++;else{done.value=true;store.clear()}}
</script>
<template><section class="section checkout-page"><div class="container"><div v-if="done" class="success-card"><div class="success-icon"><Check/></div><span class="eyebrow">Order request received</span><h1>Awaiting bakery confirmation</h1><p>Your request <b>OB-7Q4M8</b> is holding its selected capacity while the bakery reviews it. Please save your tracking link—no automated message will be sent.</p><RouterLink class="btn primary" to="/order/OB-7Q4M8">Track Your Order</RouterLink></div><template v-else><div class="checkout-head"><span class="eyebrow">Checkout</span><h1>Reserve your delivery request</h1><p>Cash on delivery. Final confirmation is always handled by the bakery.</p></div><div class="steps"><span v-for="(s,i) in ['Delivery','Schedule','Gift details']" :class="{active:i===step,done:i<step}"><b>{{i<step?'✓':i+1}}</b>{{s}}</span></div><div class="checkout-layout"><div class="checkout-form"><section v-if="step===0"><h2><MapPin/> Delivery details</h2><p class="form-note">Choose your area to see the delivery fee and available windows.</p><div class="form-grid"><label>First name<input v-model="form.first" placeholder="First name"></label><label>Last name<input v-model="form.last" placeholder="Last name"></label><label class="span2">Kuwait phone<input v-model="form.phone" placeholder="+965 9XXX XXXX"></label><label class="span2">Email <small>(optional for guest checkout)</small><input v-model="form.email" type="email"></label><label>Governorate<select v-model="form.governorate"><option disabled value="">Choose governorate</option><option>Capital</option><option>Hawalli</option><option>Farwaniya</option><option>Mubarak Al-Kabeer</option><option>Ahmadi</option><option>Jahra</option></select></label><label>Delivery area<select v-model="form.area"><option disabled value="">Choose area</option><option>Salmiya</option><option>Jabriya</option><option>Fintas</option><option>Faiha</option></select></label><label>Block<input v-model="form.block"></label><label>Street<input v-model="form.street"></label><label>Building<input v-model="form.building"></label><label>Floor / apartment <small>(if applicable)</small><input v-model="form.floor"></label><label class="span2">Delivery instructions <textarea v-model="form.instructions" placeholder="Written directions, gate code, or a preferred call time"></textarea></label></div></section><section v-if="step===1"><h2><Clock/> Delivery schedule</h2><div class="availability-notice">Your cart’s total production points and the selected area determine availability. This is a reserved request until the bakery accepts it.</div><h3>Select an available date</h3><div class="choice-grid"><button v-for="d in dates" :class="{selected:form.date===d}" @click="form.date=d">{{d}}</button></div><h3>Select a delivery window</h3><div class="choice-grid"><button v-for="t in slots" :class="{selected:form.slot===t}" @click="form.slot=t">{{t}}</button></div></section><section v-if="step===2"><h2><Gift/> Gift details</h2><label class="toggle-card"><input type="checkbox" v-model="form.gift"><span><b>This is a gift</b><small>Add recipient details and a complimentary message.</small></span></label><div v-if="form.gift" class="form-grid"><label>Recipient name<input v-model="form.recipient"></label><label>Recipient phone<input v-model="form.recipientPhone"></label><label class="span2">Gift message<textarea v-model="form.message" maxlength="200"></textarea></label><label class="toggle-card span2"><input type="checkbox" v-model="form.anonymous"><span><b>Send anonymously</b><small>Prices are always hidden from the recipient.</small></span></label></div><div class="cod-notice"><Wallet/> <span><b>Cash on delivery</b><small>Payment is collected by the driver after delivery. No cards or online payment methods are accepted.</small></span></div></section><div class="checkout-actions"><button class="btn secondary" :disabled="step===0" @click="step--"><ArrowLeft :size="17"/> Back</button><button class="btn primary" @click="next">{{step===2?'Submit order request':'Continue'}} <ArrowRight :size="17"/></button></div></div><aside class="summary"><h2>Your Order</h2><div v-for="item in store.cart" class="mini-order"><img :src="item.product.image"><span><b>{{item.product.name}}</b><small>Qty {{item.quantity}}</small></span><strong>{{money(item.product.price*item.quantity)}}</strong></div><div><span>Subtotal</span><b>{{money(store.cartTotal)}}</b></div><div><span>Area delivery fee</span><b>{{deliveryFee===null?'Select area':money(deliveryFee)}}</b></div><div class="total"><span>Total</span><b>{{money(total)}}</b></div><p>Final price and availability are verified by the bakery before your reservation is created.</p></aside></div></template></div></section></template>
